package parser
import("encoding/json";"os";"testing";"unicode/utf16";"strconv";"github.com/microsoft/TypeScript/tsc/internal/ast";"github.com/microsoft/TypeScript/tsc/internal/core";"github.com/microsoft/TypeScript/tsc/internal/locale";"github.com/microsoft/TypeScript/tsc/internal/stringutil")
func TestTscsJsonAstOracle(t *testing.T){
 b,e:=os.ReadFile(os.Getenv("TSCS_STRING_INPUT"));if e!=nil{t.Fatal(e)};var rows []struct{ID string `json:"id"`;Source string `json:"source"`};if e=json.Unmarshal(b,&rows);e!=nil{t.Fatal(e)};out:=[]map[string]any{}
 for _,r:=range rows{sf:=ParseSourceFile(ast.SourceFileParseOptions{FileName:"/tsconfig.json"},r.Source,core.ScriptKindJSON);offset:=func(p int)int{return len(utf16.Encode([]rune(r.Source[:p])))};nodes:=[]map[string]any{};var walk func(*ast.Node,string)
 walk=func(n *ast.Node,path string){if n==nil{return};kind:="";value:="";number:="";switch n.Kind{case ast.KindObjectLiteralExpression:kind="Object";case ast.KindArrayLiteralExpression:kind="Array";case ast.KindStringLiteral:kind="String";value=n.Text();case ast.KindIdentifier:kind="Identifier";value=n.Text();case ast.KindNumericLiteral:kind="Number";number=n.Text();case ast.KindPrefixUnaryExpression:kind="Number";number="-"+n.AsPrefixUnaryExpression().Operand.Text();case ast.KindTrueKeyword:kind="True";case ast.KindFalseKeyword:kind="False";case ast.KindNullKeyword:kind="Null";default:t.Fatalf("unmapped kind %v",n.Kind)};units:=[]uint16{};for len(value)>0{c,z:=stringutil.DecodeJSStringRune(value);value=value[z:];if c<=0xffff{units=append(units,uint16(c))}else{units=append(units,utf16.Encode([]rune{c})...)}};span:=getErrorSpanForNode(r.Source,n);nodes=append(nodes,map[string]any{"path":path,"kind":kind,"start":offset(span.Pos()),"end":offset(span.End()),"number":number,"units":units})
 if kind=="Object"{for i,p:=range n.AsObjectLiteralExpression().Properties.Nodes{if p.Kind!=ast.KindPropertyAssignment{t.Fatal("unsupported oracle property")};walk(p.Name(),path+"/p"+strconv.Itoa(i)+"/name");walk(p.AsPropertyAssignment().Initializer,path+"/p"+strconv.Itoa(i)+"/value")}}else if kind=="Array"{for i,v:=range n.Elements(){walk(v,path+"/e"+strconv.Itoa(i))}}
 };if len(sf.Statements.Nodes)>0{walk(sf.Statements.Nodes[0].Expression(),"$")};ds:=[]map[string]any{};for _,d:=range sf.Diagnostics(){ds=append(ds,map[string]any{"code":d.Code(),"start":offset(d.Pos()),"length":offset(d.End())-offset(d.Pos()),"message":d.Localize(locale.Default)})};out=append(out,map[string]any{"id":r.ID,"source":r.Source,"nodes":nodes,"diagnostics":ds})}
 b,e=json.MarshalIndent(out,"","  ");if e!=nil{t.Fatal(e)};if e=os.WriteFile(os.Getenv("TSCS_STRING_OUTPUT"),b,0600);e!=nil{t.Fatal(e)}
}
